INSERT INTO `product_return_policy` (`id`, `title`, `policy_validity`, `policy_type_refund`, `policy_type_replace`, `policy_type_exchange`, `policy`, `status`, `created_at`, `updated_at`, `created_by`) VALUES
(2, '02 Days Return & Exchange ', 2, 1, 1, 1, '&lt;ul&gt;\r\n&lt;li&gt;02 Days Refund against Return (For more details please go through our Return &amp; refund policy)&lt;/li&gt;\r\n&lt;li&gt;07 Days Exchange of Products ( For more details go through our Return Policy)&lt;/li&gt;\r\n&lt;li&gt;Missing items, damaged items: please inform us within 2 business days of the delivery date if there are any problems with your order.&lt;/li&gt;\r\n&lt;li&gt;We strongly Recommend that Make video of Product Unboxing for hassle free Return &amp; Exchange.&lt;/li&gt;\r\n&lt;/ul&gt;', 1, '2022-09-22 02:16:26', '2022-09-22 08:46:26', '1'),
(3, '7 Days Exchange Policy ', 7, 1, 1, 1, '&lt;p&gt;&lt;strong&gt;New Policy&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;Exchange Policy:- exchange your existing products in duration of 07 days after delivery as per Return &amp; refund policy mentioned at our policy page&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;&nbsp;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;&nbsp;&lt;/strong&gt;&lt;/p&gt;', 1, '2023-05-15 05:50:54', '2023-05-15 12:20:54', '1');
