CREATE TABLE `wallet_transaction_history` (
  `id` int(11) NOT NULL,
  `wallet_id` varchar(50) NOT NULL,
  `payment_type` varchar(20) NOT NULL COMMENT '0- prod. commission / 1 - membership reward  / 2 -  checkout_discount / 3- withdwrowal / 4 - Seller commission,5 add money to wallet, 6 deduct New User Bonus, 7 deduct Virtual Partner/Order Commission,8 return order cancel New User Bonus, 9 return order cancel Virtual Partner/Order Commission',
  `transaction_id` varchar(50) NOT NULL,
  `transaction_type` varchar(50) NOT NULL,
  `amount` varchar(50) NOT NULL,
  `balance` varchar(50) NOT NULL,
  `product_id` varchar(50) NOT NULL,
  `order_id` varchar(50) NOT NULL,
  `user_id` varchar(50) NOT NULL,
  `remark` text NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

